def _execution_skills(contexts,triggers=(),risk="R1",packs=()):
    contexts=set(contexts or ()); triggers=set(triggers or ()); packs=set(packs or ())
    pure_style=(triggers=={"UI_STYLE_CHANGED"} and RISK_ORDER.get(risk,1)<=0)
    names=[]
    for ctx in sorted(contexts):
        if pure_style and ctx=="WEB_UI":
            continue
        names.extend(CONTEXT_TO_EXECUTION_SKILLS.get(ctx,[]))
    # Cross-layer application work.
    application_layers=sum(x in contexts for x in ("WEB_UI","PUBLIC_API","DATABASE"))
    if application_layers>=2 and not pure_style:
        names.append(FULL_STACK_INTEGRATION_SKILL)
    # Runtime/reliability playbook only where operational depth is proportionate.
    if (
        RISK_ORDER.get(risk,1)>=2
        and ({"PUBLIC_API","BACKGROUND_JOB"} & contexts)
    ) or ({"RELEASE_ENGINEERING","PERFORMANCE_CAPACITY_COST","INFRASTRUCTURE_IAC"} & packs):
        names.append(RELIABILITY_SKILL)
    return list(dict.fromkeys(names))

