# ---------- embedded project scan / policy ----------
def scan(repo):
    repo=Path(repo).resolve(); td,root=_runtime_root()
    try: return _load_bootstrap(root).scan_repo(repo)
    finally: td.cleanup()

def assess(repo,base="HEAD"):
    repo=Path(repo).resolve(); td,root=_runtime_root()
    try: return _load_bootstrap(root).assess_git(repo,base,True)
    finally: td.cleanup()

def guidance(repo,base="HEAD",assessment=None):
    repo=Path(repo).resolve(); a=assessment or assess(repo,base); names=set(CORE_SKILLS)
    for s in a.get("skills",[]):
        if isinstance(s,dict) and s.get("name"): names.add(s["name"])
    for route in a.get("required_context_packs",[]):
        if route in ROUTE_TO_SKILL: names.add(ROUTE_TO_SKILL[route])
    actual_web_contexts,actual_web_evidence=_actual_web_execution_contexts(repo,a)
    execution_contexts=sorted(set(a.get("contexts",[]))|set(actual_web_contexts))
    for name in _execution_skills(execution_contexts,a.get("triggers",[]),a.get("risk","R1"),a.get("required_context_packs",[])):
        names.add(name)
    td,root=_runtime_root(); docs=[]
    try:
        for name in sorted(names):
            p=root/".agents/skills"/name/"SKILL.md"
            if p.exists(): docs.append({"skill":name,"content":p.read_text(encoding="utf-8")})
    finally: td.cleanup()
    return {"assessment_summary":{"risk":a.get("risk"),"triggers":a.get("triggers",[]),"packs":a.get("required_context_packs",[]),"selected_controls":a.get("selected_control_count"),"specialist_controls":a.get("specialist_control_count"),"execution_contexts":execution_contexts,"actual_web_detection":actual_web_evidence},"procedures":docs}

def _load_embedded_skill_docs(names):
    td,root=_runtime_root(); docs=[]; missing=[]
    try:
        for name in list(dict.fromkeys(names or [])):
            p=root/".agents/skills"/name/"SKILL.md"
            if p.exists(): docs.append({"skill":name,"content":p.read_text(encoding="utf-8")})
            else: missing.append(name)
    finally: td.cleanup()
    return docs,missing

def task_guidance(repo="."):
    repo=Path(repo).resolve(); state=_load_json(_state_path(repo),{}); plan=state.get("current_task")
    if not plan:
        return {"status":"BLOCKED","reason":"NO_SAVED_TASK_PLAN","agent_action":"Run plan --save first."}
    docs,missing=_load_embedded_skill_docs(plan.get("procedures",[]))
    if missing:
        return {"status":"BLOCKED","reason":"PROCEDURE_NOT_AVAILABLE","missing":missing,"task_id":plan.get("task_id")}
    return {"status":"PASS","task_id":plan.get("task_id"),"request":plan.get("request"),"risk":plan.get("assessment",{}).get("risk"),"execution_contexts":plan.get("assessment",{}).get("execution_contexts",[]),"required_packs":plan.get("assessment",{}).get("required_packs",[]),"procedure_count":len(docs),"procedures":docs,"agent_instruction":"Apply these procedures during implementation. If actual diff reveals new domains/routes, load guidance for actual diff and re-verify."}

# ---------- installation ----------
def _merge_profile(existing,detected):
    if not isinstance(existing,dict): existing={}
    out=copy.deepcopy(existing); out["framework_version"]=VERSION
    out.setdefault("project",detected.get("project",{})); out.setdefault("contexts",[])
    out["contexts"]=sorted(set(out["contexts"])|set(detected.get("contexts",[])))
    decisions=out.setdefault("context_decisions",{})
    candidates=[]
    for c in detected.get("context_candidates",[]):
        if c.get("context") not in decisions: candidates.append(c)
    out["context_candidates"]=candidates
    out["environments"]=out.get("environments") or detected.get("environments",["LOCAL"])
    out["stack"]=detected.get("stack",out.get("stack",{})); out["commands"]=detected.get("commands",out.get("commands",{}))
    out["command_sets"]=detected.get("command_sets",out.get("command_sets",[])); out.setdefault("profiles",[])
    out["detection"]=detected.get("detection",{}); out["requires_confirmation"]=detected.get("requires_confirmation",[])
    return out

def compact_plan(repo,github=False):
    repo=Path(repo).resolve(); profile=scan(repo) if repo.exists() else {"contexts":[],"context_candidates":[],"project":{"name":repo.name,"type":"software","criticality":"STANDARD"},"commands":{},"command_sets":[],"stack":{},"profiles":[],"environments":["LOCAL"]}
    actions=[]; conflicts=[]
    rt=repo/".sef/sef.py"
    if rt.exists():
        head=rt.read_text(encoding="utf-8",errors="ignore")[:300]
        if "SEF_PROJECT_ENGINEERING_OS" in head or "SEF_COMPACT_RUNTIME" in head: actions.append({"path":".sef/sef.py","action":"UPDATE_WITH_BACKUP"})
        else: conflicts.append({"path":".sef/sef.py","reason":"unmanaged existing file"})
    else: actions.append({"path":".sef/sef.py","action":"CREATE"})
    skill=repo/".agents/skills/senior-engineering-framework/SKILL.md"
    if skill.exists() and "Senior Engineering Framework" not in skill.read_text(encoding="utf-8",errors="ignore"):
        conflicts.append({"path":str(skill.relative_to(repo)),"reason":"user-owned same-name skill"})
    else: actions.append({"path":".agents/skills/senior-engineering-framework/SKILL.md","action":"UPDATE" if skill.exists() else "CREATE"})
    for rel in ["AGENTS.md",".sef/project-profile.json",".sef/project-baseline.json",".sef/installation.json"]:
        actions.append({"path":rel,"action":"MERGE" if (repo/rel).exists() else "CREATE"})
    if github:
        wf=repo/".github/workflows/sef-policy.yml"
        if wf.exists() and "SEF Project Engineering OS" not in wf.read_text(encoding="utf-8",errors="ignore"):
            actions.append({"path":".sef/sef-policy.proposed.yml","action":"CREATE_PROPOSAL_PRESERVE_EXISTING_WORKFLOW"})
        else: actions.append({"path":".github/workflows/sef-policy.yml","action":"UPDATE" if wf.exists() else "CREATE"})
    return {"status":"BLOCKED" if conflicts else "PASS","version":VERSION,"repo":str(repo),"managed_file_count":len(actions),"actions":actions,"conflicts":conflicts,"detected_profile":profile}

# ---------- project engineering baseline ----------
def _derived_project_requirements(profile):
    ctx=set(profile.get("contexts",[])); req=[]
    req += [
      {"domain":"requirements","requirement":"Maintain explicit product scope, acceptance criteria, assumptions and unresolved decisions for material work."},
      {"domain":"maintainability","requirement":"Keep code boundaries, naming, dependencies and change scope understandable and maintainable; avoid unnecessary coupling and hidden side effects."},
      {"domain":"verification","requirement":"Every material change requires direct verification; riskier changes require stronger independent evidence."},
      {"domain":"source-control","requirement":"Preserve traceable source history and unrelated user work; releases must identify an exact revision/artifact."},
      {"domain":"security","requirement":"Apply least privilege, secret protection, input/trust-boundary controls and specialist security review when security-sensitive surfaces are present."},
    ]
    if "WEB_UI" in ctx: req += [
      {"domain":"ui","requirement":"Define supported client/browser/device behavior for critical journeys and consider accessibility proportionately."}]
    if "PUBLIC_API" in ctx: req += [
      {"domain":"api","requirement":"Define API contracts, validation, error semantics, authorization boundaries, compatibility and abuse/rate-limit behavior where relevant."}]
    if "DATABASE" in ctx: req += [
      {"domain":"data","requirement":"Define data ownership/invariants, migration compatibility, backup/recovery expectations and destructive-change controls."}]
    if "DOCKER" in ctx: req += [
      {"domain":"containers","requirement":"Keep build/runtime environments reproducible, secrets out of images, privileges minimal and release images identifiable."}]
    if "IAC" in ctx: req += [
      {"domain":"infrastructure","requirement":"Review planned infrastructure diffs, protect state/secrets, constrain network exposure and preserve operator recovery."}]
    if "AI_LLM" in ctx or "AGENTIC_RUNTIME" in ctx: req += [
      {"domain":"ai","requirement":"Define model/tool/data boundaries, evaluation/adversarial testing, cost limits and safe failure behavior; model confidence is not authorization."}]
    if "BACKGROUND_JOB" in ctx: req += [
      {"domain":"async","requirement":"Define retry/idempotency, queue/backlog behavior, failure handling and observability for background work."}]
    if "CACHE" in ctx: req += [
      {"domain":"cache","requirement":"Define freshness/invalidation, key scope, cold-start/stampede behavior and correctness without cache."}]
    if "INBOUND_WEBHOOK" in ctx: req += [
      {"domain":"webhook","requirement":"Verify webhook authenticity, replay/duplicate behavior, payload validation and local authorization before side effects."}]
    if "FILE_UPLOAD" in ctx: req += [
      {"domain":"upload","requirement":"Treat uploads as hostile input: validate type/content/size, authorize storage/access and bound parser/malware/resource risk."}]
    if "PAYMENTS" in ctx: req += [
      {"domain":"payments","requirement":"Treat financial side effects as high-impact: idempotency, exact amounts/currency/state transitions, auditability and human/business approval policy where applicable."}]
    return req

def _analyze_brief(brief):
    t=(brief or "").lower(); signals=[]; domains=set(); candidates=[]; inferred=[]
    def hit(p): return re.search(p,t,re.I) is not None
    def sig(name,why): signals.append({"signal":name,"reason":why})
    if hit(r"\b(saas|logiciel en ligne|plateforme web|web app|application web)\b"):
        sig("SAAS_PRODUCT","web/SaaS product in brief"); domains.update(["WEB_UI","PUBLIC_API","DATABASE"])
        candidates.append("MULTI_TENANT"); inferred += ["identity/access model","data persistence","environment/release ownership"]
    if hit(r"\b(b2b|entreprise|entreprises|company|companies|organisation|organization|workspace|équipe|team)\b"):
        sig("B2B_ORGANIZATIONS","organization/team usage in brief"); candidates.append("MULTI_TENANT"); inferred += ["organization membership and role model","tenant/customer boundary decision"]
    if hit(r"\b(réservations?|reservations?|bookings?|rendez[- ]?vous|appointments?|planning|planification|schedule|courses?|trajets?|dispatch)\b"):
        sig("SCHEDULING_DOMAIN","booking/scheduling semantics in brief"); domains.update(["DATABASE","TIME_SENSITIVE"]); inferred += ["timezone/DST semantics","booking state machine","concurrency/conflict policy","idempotent side effects"]
    if hit(r"\b(clients?|customers?|utilisateurs?|users?|chauffeurs?|drivers?|patients?|candidats?|employees?|salariés?)\b"):
        sig("USER_ACCOUNTS_OR_PEOPLE","people/customer records in brief"); candidates.append("PII"); inferred += ["identity and authorization model","data classification and retention"]
    if hit(r"\b(paiement|payment|facturation|billing|stripe|invoice|abonnement|subscription)\b"):
        sig("PAYMENTS","payments/billing in brief"); domains.update(["PAYMENTS","EXTERNAL_SAAS"]); inferred += ["financial idempotency","audit trail","provider failure/reconciliation"]
    if hit(r"\b(ia|ai|llm|agent|assistant|rag|openai|anthropic|gemini)\b"):
        sig("AI_CAPABILITY","AI/agent capability in brief"); domains.add("AI_LLM"); inferred += ["model/tool/data boundaries","evaluation and safe failure","cost limits"]
    if hit(r"\b(webhook|api externe|external api|intégration|integration|crm|erp)\b"):
        sig("INTEGRATIONS","external integrations in brief"); domains.add("EXTERNAL_SAAS"); inferred += ["contract/versioning","timeouts/retries","supplier ownership"]
    if hit(r"\b(fichier|document|upload|pièce jointe|attachment|import csv|import excel)\b"):
        sig("FILE_HANDLING","file handling in brief"); domains.add("FILE_UPLOAD"); inferred += ["hostile file validation","storage/access lifecycle"]
    if hit(r"\b(médical|medical|santé|health|finance réglementée|regulated|juridique|legal decision)\b"):
        sig("REGULATED_OR_HIGH_IMPACT","regulated/high-impact domain language"); candidates.append("REGULATED_DOMAIN")
    return {"signals":signals,"design_domains":sorted(domains),"context_candidates":sorted(set(candidates)),"inferred_design_concerns":list(dict.fromkeys(inferred))}

def _baseline(repo,brief="",mode="ADOPT"):
    repo=Path(repo).resolve(); profile=_load_json(repo/".sef/project-profile.json",scan(repo)); brief_analysis=_analyze_brief(brief)
    candidates=profile.get("context_candidates",[])
    confirmations=sorted(set([c.get("context") for c in candidates if c.get("context")]+brief_analysis.get("context_candidates",[])))
    unknowns=[]
    if not brief.strip(): unknowns.append({"id":"PRODUCT_BRIEF","question":"What problem is the product solving, for whom, and what outcome defines success?","blocking_for":"material product design"})
    unknowns += [{"id":x,"question":q,"blocking_for":"related high-impact decisions"} for x,q in [
      ("USERS_STAKEHOLDERS","Who are the primary users, operators, owners and approvers?"),
      ("DATA_CLASSIFICATION","What personal, confidential, financial or regulated data is processed?"),
      ("CRITICALITY","What availability/data-loss/business-impact level is acceptable?"),
      ("PRODUCTION_MODEL","How will environments, deployment, rollback and operations be owned?"),
    ]]
    return {
      "schema_version":"1.0","framework_version":VERSION,"updated_at":_now(),
      "project":{
        "name":profile.get("project",{}).get("name",repo.name),
        "mode":mode,"brief":brief.strip(),
        "lifecycle_stage":"DISCOVERY" if mode=="INIT" else "ADOPTION",
        "criticality":profile.get("project",{}).get("criticality","STANDARD"),
        "users":[],"stakeholders":[],"business_outcomes":[],"in_scope":[],"out_of_scope":[]
      },
      "discovery":{
        "assumptions":[],"constraints":[],"unknowns":unknowns,
        "context_confirmations_needed":confirmations
      },
      "requirements":{
        "functional":[],
        "inferred_professional":_derived_project_requirements(profile)+[
          {"domain":"project-design","requirement":x} for x in brief_analysis.get("inferred_design_concerns",[])
        ],
        "non_functional_targets":{
          "security":"risk-based","privacy":"determine applicability","reliability":"define criticality/RPO/RTO if material",
          "performance":"define budgets where user/business sensitive","accessibility":"define applicable target for user-facing surfaces",
          "compatibility":"define supported clients/contracts","maintainability":"required","observability":"required for production-critical paths"
        }
      },
      "architecture":{
        "observed_project_type":profile.get("project",{}).get("type"),
        "contexts":profile.get("contexts",[]),"stack":profile.get("stack",{}),
        "brief_analysis":brief_analysis,
        "design_domains":brief_analysis.get("design_domains",[]),
        "boundaries":[],"data_stores":[],"external_services":[],"decisions":[]
      },
      "engineering_strategy":{
        "risk_model":"R0-R4","action_model":"A0-A4","commands":profile.get("commands",{}),"command_sets":profile.get("command_sets",[]),
        "test_strategy":["direct verification for every material change","risk-based unit/integration/e2e/negative/security/performance/recovery evidence"],
        "release_strategy":["exact release identity","policy-derived release readiness","progressive delivery/rollback when risk warrants"],
        "recovery_strategy":["define rollback/roll-forward and data recovery before destructive/irreversible production work"],
        "evidence_policy":"PASS requires compatible evidence; NOT_RUN/UNAVAILABLE/INCONCLUSIVE are not PASS"
      },
      "definition_of_done":{
        "project_level":[
          "material requirements and acceptance criteria are explicit",
          "architecture/data/security implications are addressed proportionately",
          "implementation remains within intended scope or records deliberate decisions",
          "required verification evidence passes",
          "known residual risk is explicit and owned",
          "release has exact identity, recovery/rollback semantics and required approvals"
        ],
        "dynamic_per_task":True
      },
      "governance":{
        "agent_constitution":"AGENTS.md","project_profile":".sef/project-profile.json",
        "no_agent_self_approval":True,"preserve_user_work":True,"production_requires_policy_gate":True
      },
      "status":{
        "baseline_state":"NEEDS_DISCOVERY" if not brief.strip() else ("INITIALIZED_WITH_OPEN_QUESTIONS" if mode=="INIT" else "ADOPTED_WITH_OPEN_QUESTIONS"),
        "open_question_count":len(unknowns)+len(confirmations),"last_audit":None
      }
    }

def _save_baseline(repo,brief="",mode="ADOPT",merge_existing=True):
    repo=Path(repo).resolve(); new=_baseline(repo,brief,mode); path=repo/".sef/project-baseline.json"
    if merge_existing and path.exists():
        old=_load_json(path,{})
        # Preserve user/domain content while refreshing observed architecture/strategy.
        merged=_deep_merge(new,old)
        merged["framework_version"]=VERSION; merged["updated_at"]=_now()
        # New brief explicitly replaces blank/old brief if supplied.
        if brief.strip(): merged.setdefault("project",{})["brief"]=brief.strip()
        new=merged
    _write_json(path,new); return new

def install(repo,github=False,brief="",mode="ADOPT"):
    repo=Path(repo).resolve(); repo.mkdir(parents=True,exist_ok=True)
    plan=compact_plan(repo,github)
    if plan["status"]!="PASS": return plan
    rt=repo/".sef/sef.py"; rt.parent.mkdir(parents=True,exist_ok=True)
    if rt.exists(): _backup(repo,Path(".sef/sef.py"))
    shutil.copy2(Path(__file__).resolve(),rt); os.chmod(rt,0o755)
    skill=repo/".agents/skills/senior-engineering-framework/SKILL.md"; skill.parent.mkdir(parents=True,exist_ok=True); skill.write_text(UMBRELLA_SKILL,encoding="utf-8")
    ag=repo/"AGENTS.md"; old=ag.read_text(encoding="utf-8",errors="ignore") if ag.exists() else ""
    if ag.exists(): _backup(repo,Path("AGENTS.md"))
    ag.write_text(_merge_agents(old),encoding="utf-8")
    cl=repo/"CLAUDE.md"; cold=cl.read_text(encoding="utf-8",errors="ignore") if cl.exists() else ""
    if cl.exists(): _backup(repo,Path("CLAUDE.md"))
    cl.write_text(_merge_claude(cold),encoding="utf-8")
    profile=plan["detected_profile"]; pp=repo/".sef/project-profile.json"
    if pp.exists(): _backup(repo,Path(".sef/project-profile.json"))
    _write_json(pp,_merge_profile(_load_json(pp,{}),profile))
    baseline=_save_baseline(repo,brief,mode,merge_existing=True)
    _write_json(repo/".sef/installation.json",{
      "framework":"SEF Project Engineering OS","version":VERSION,"installed_at":_now(),"mode":mode,
      "agent_adapters":["codex","claude-code"],
      "managed_files":["AGENTS.md","CLAUDE.md",".sef/sef.py",".sef/project-profile.json",".sef/project-baseline.json",".sef/installation.json",".agents/skills/senior-engineering-framework/SKILL.md"]})
    if github:
        wf=repo/".github/workflows/sef-policy.yml"
        if wf.exists() and "SEF Project Engineering OS" not in wf.read_text(encoding="utf-8",errors="ignore"):
            (repo/".sef/sef-policy.proposed.yml").write_text(WORKFLOW,encoding="utf-8")
        else:
            wf.parent.mkdir(parents=True,exist_ok=True); wf.write_text(WORKFLOW,encoding="utf-8")
    return {"status":"PASS","version":VERSION,"repo":str(repo),"mode":mode,"managed_sef_files":7,"contexts":profile.get("contexts",[]),"baseline_state":baseline.get("status",{}).get("baseline_state"),"next":"python3 .sef/sef.py audit ."}

def init_project(repo,brief="",github=False,no_git=False):
    repo=Path(repo).resolve(); repo.mkdir(parents=True,exist_ok=True)
    if not no_git and not _is_git(repo):
        cp=_run(["git","init","-q"],repo,timeout=30)
        if cp.returncode!=0: return {"status":"BLOCKED","reason":"GIT_INIT_FAILED","stderr":cp.stderr.strip()}
    return install(repo,github=github,brief=brief,mode="INIT")

def adopt_project(repo,brief="",github=False): return install(repo,github=github,brief=brief,mode="ADOPT")

# ---------- Codex-operated bootstrap / session ----------
def _meaningful_project_files(repo):
    """Project files that indicate an existing codebase rather than a fresh SEF drop."""
    repo=Path(repo).resolve()
    ignore_names={"sef.py","README.md","README.txt",".DS_Store"}
    ignore_dirs={".git",".sef",".agents","__pycache__","node_modules",".venv","venv",".next","dist","build"}
    out=[]
    if not repo.exists(): return out
    for root,dirs,files in os.walk(repo):
        dirs[:]=[d for d in dirs if d not in ignore_dirs]
        for name in files:
            path=Path(root)/name
            try: rel=path.relative_to(repo).as_posix()
            except ValueError: continue
            if "/" not in rel and name in ignore_names: continue
            if rel.startswith(".github/workflows/sef-policy"): continue
            out.append(rel)
            if len(out)>=100: return sorted(out)
    return sorted(out)

def _auto_project_mode(repo):
    repo=Path(repo).resolve()
    meaningful=_meaningful_project_files(repo)
    if meaningful:
        return "ADOPT",{"reason":"existing project files detected","sample_files":meaningful[:12]}
    # A Git repository with an existing commit can still be an intentionally empty skeleton,
    # but adoption is safer if history already exists.
    if _is_git(repo):
        cp=_git(repo,"rev-parse","--verify","HEAD")
        if cp.returncode==0:
            tracked=_git(repo,"ls-tree","-r","--name-only","HEAD")
            names=[x.strip() for x in tracked.stdout.splitlines() if x.strip() and x.strip() not in {"sef.py","README.md","README.txt"}]
            if names:
                return "ADOPT",{"reason":"existing Git history contains project files","sample_files":names[:12]}
    return "INIT",{"reason":"no existing project implementation detected","sample_files":[]}

def _user_question_for_context(context):
    questions={
      "PII":"Le produit traite-t-il des données personnelles ou identifiantes réelles (par exemple email, téléphone, nom, adresse, localisation) ?",
      "MULTI_TENANT":"Plusieurs organisations/clients utiliseront-ils la même application ou infrastructure avec une séparation logique de leurs données ?",
      "REGULATED_DOMAIN":"Le produit est-il soumis à un domaine réglementé ou à des décisions à fort impact (santé, finance réglementée, juridique, sécurité critique, etc.) ?",
      "CUSTOMER_CRITICAL":"Une indisponibilité ou erreur de ce système peut-elle bloquer une activité client importante ou provoquer un impact métier significatif ?",
      "HIGH_AVAILABILITY":"Le produit a-t-il une exigence explicite de haute disponibilité ou de continuité de service ?",
      "PRODUCTION":"Ce repository/service correspond-il déjà à un système exploité en production ?"
    }
    return questions.get(context,f"Confirmer le contexte projet `{context}` avant les décisions à fort impact.")

def _agent_handoff(repo,mode,bootstrap_result=None):
    repo=Path(repo).resolve()
    profile=_load_json(repo/".sef/project-profile.json",{})
    baseline=_load_json(repo/".sef/project-baseline.json",{})
    a=audit(repo)
    material_candidates=sorted(set(
        [c.get("context") for c in profile.get("context_candidates",[]) if c.get("context") in MATERIAL_CONFIRMATIONS]
        + [ctx for ctx in baseline.get("discovery",{}).get("context_confirmations_needed",[]) if ctx in MATERIAL_CONFIRMATIONS]
    ))
    unknowns=baseline.get("discovery",{}).get("unknowns",[])
    user_questions=[]
    # Only questions whose answer is an authoritative product/business/world fact.
    for u in unknowns:
        if u.get("id")=="PRODUCT_BRIEF":
            user_questions.append(u.get("question"))
        elif u.get("id")=="USERS_STAKEHOLDERS":
            user_questions.append("Qui sont les utilisateurs principaux, les opérateurs métier et les personnes autorisées à approuver les actions sensibles ?")
        elif u.get("id")=="DATA_CLASSIFICATION" and not material_candidates:
            user_questions.append("Quelles catégories de données réelles le produit doit-il traiter : personnelles, confidentielles, financières ou réglementées ?")
        elif u.get("id")=="CRITICALITY":
            user_questions.append("Quel serait l'impact métier acceptable d'une indisponibilité ou d'une perte de données : faible, significatif ou critique ?")
    for ctx in sorted(set(material_candidates)):
        q=_user_question_for_context(ctx)
        if q not in user_questions: user_questions.append(q)

    material_block=bool(
        not baseline.get("project",{}).get("brief")
        or material_candidates
        or a.get("project_readiness")=="BLOCKED"
    )
    # The agent can continue discovery/architecture work, but should not start material
    # implementation while authoritative context required for the design is unresolved.
    stage="DISCOVERY_REQUIRED" if material_block else (
        "READY_WITH_OPEN_QUESTIONS" if a.get("findings") else "READY_FOR_ENGINEERING"
    )
    return {
      "protocol":"SEF_AGENT_HANDOFF_V1",
      "project_mode":mode,
      "agent_adapters":["codex","claude-code"],
      "python_runtime":python_runtime_info(),
      "stage":stage,
      "continue_current_agent_session":True,
      "must_read":[
        "AGENTS.md",
        "CLAUDE.md",
        ".sef/project-baseline.json",
        ".sef/project-profile.json",
        ".agents/skills/senior-engineering-framework/SKILL.md"
      ],
      "next_command_template":"<available-python3> .sef/sef.py session .",
      "implementation_policy":{
        "may_inspect_and_design":True,
        "material_implementation_allowed":not material_block,
        "rule":"Resolve authoritative material project facts before irreversible/high-impact implementation. Do not ask the user to choose routine senior-engineering controls."
      },
      "questions_to_user":user_questions[:8],
      "record_user_answers":{
        "context_decision":"python3 .sef/sef.py confirm . <CONTEXT> yes|no --reason \"<authoritative user answer>\"",
        "structured_discovery":"python3 .sef/sef.py intake . --answers <temporary-json-file>",
        "after_recording":"python3 .sef/sef.py session ."
      },
      "agent_responsibilities":[
        "Infer professional software-engineering requirements the user did not know to state.",
        "Propose architecture, test, security, recovery, observability and release controls proportionate to risk.",
        "Ask the user only for product/business/world facts or approvals that cannot be responsibly inferred.",
        "Run SEF plan before non-trivial implementation, verify before DONE, and release gate before production.",
        "Do not claim PASS for missing, skipped, unavailable or inconclusive evidence."
      ],
      "bootstrap_result":bootstrap_result
    }

def agent_start(repo=".",brief="",github=False,mode="AUTO",no_git=False):
    """Generic first-turn bootstrap for Codex, Claude Code, and compatible shell-capable coding agents."""
    repo=Path(repo).resolve(); repo.mkdir(parents=True,exist_ok=True)
    st=self_test()
    if st.get("status")!="PASS":
        return {"status":"BLOCKED","reason":"SELF_TEST_FAILED","self_test":st}
    requested=str(mode or "AUTO").upper()
    if requested not in {"AUTO","INIT","ADOPT"}:
        return {"status":"BLOCKED","reason":"INVALID_MODE","allowed":["AUTO","INIT","ADOPT"]}
    if (repo/".sef/installation.json").exists():
        existing=_load_json(repo/".sef/installation.json",{})
        existing_mode=existing.get("mode","ADOPT")
        installed_version=str(existing.get("version") or "")
        if installed_version!=VERSION:
            existing_baseline=_load_json(repo/".sef/project-baseline.json",{})
            effective_brief=brief.strip() or existing_baseline.get("project",{}).get("brief","")
            upgrade_result=install(repo,github=github,brief=effective_brief,mode=existing_mode)
            if upgrade_result.get("status")!="PASS":
                return {
                  "status":upgrade_result.get("status","BLOCKED"),"reason":"UPGRADE_FAILED",
                  "from_version":installed_version,"to_version":VERSION,
                  "bootstrap_result":upgrade_result
                }
            return {
              "status":"PASS","version":VERSION,"upgraded":True,
              "from_version":installed_version,"to_version":VERSION,
              "repo":str(repo),"mode":existing_mode,
              "agent_handoff":_agent_handoff(repo,existing_mode,upgrade_result)
            }
        if brief.strip():
            intake(repo,brief=brief)
        return {
          "status":"PASS","version":VERSION,"already_installed":True,
          "repo":str(repo),"mode":existing_mode,
          "agent_handoff":_agent_handoff(repo,existing_mode,{"status":"ALREADY_INSTALLED"})
        }
    if requested=="AUTO":
        chosen,why=_auto_project_mode(repo)
    else:
        chosen,why=requested,{"reason":"explicit mode requested"}
    if chosen=="INIT":
        result=init_project(repo,brief=brief,github=github,no_git=no_git)
    else:
        result=adopt_project(repo,brief=brief,github=github)
    if result.get("status")!="PASS":
        return {"status":result.get("status","BLOCKED"),"version":VERSION,"repo":str(repo),"mode":chosen,"mode_detection":why,"bootstrap_result":result}
    return {
      "status":"PASS","version":VERSION,"repo":str(repo),"mode":chosen,
      "mode_detection":why,
      "user_action_required":"ANSWER_ONLY_AUTHORITATIVE_PROJECT_QUESTIONS",
      "agent_handoff":_agent_handoff(repo,chosen,result)
    }

def codex_start(repo=".",brief="",github=False,mode="AUTO",no_git=False):
    """Backward-compatible alias for agent_start."""
    return agent_start(repo,brief,github,mode,no_git)

def session(repo="."):
    """Read-only engineering handoff for a new Codex session/non-trivial task."""
    repo=Path(repo).resolve()
    if not (repo/".sef/installation.json").exists():
        return {
          "status":"BLOCKED","reason":"SEF_NOT_INITIALIZED",
          "agent_action":"If a root sef.py exists, run it with an available Python 3 interpreter: sef.py agent-start . --brief \"<user project brief>\""
        }
    d=doctor(repo)
    if d.get("status")!="PASS":
        return {"status":"BLOCKED","reason":"SEF_DOCTOR_FAILED","doctor":d}
    profile=_load_json(repo/".sef/project-profile.json",{})
    baseline=_load_json(repo/".sef/project-baseline.json",{})
    runtime=_load_json(_state_path(repo),{})
    a=audit(repo)
    material_candidates=sorted(set(
        [c.get("context") for c in profile.get("context_candidates",[]) if c.get("context") in MATERIAL_CONFIRMATIONS]
        + [ctx for ctx in baseline.get("discovery",{}).get("context_confirmations_needed",[]) if ctx in MATERIAL_CONFIRMATIONS]
    ))
    gate="DISCOVERY_REQUIRED" if (
        not baseline.get("project",{}).get("brief")
        or material_candidates
        or a.get("project_readiness")=="BLOCKED"
    ) else ("READY_WITH_OPEN_QUESTIONS" if a.get("findings") else "READY")
    return {
      "status":"PASS","protocol":"SEF_SESSION_V1","framework_version":VERSION,
      "project":{
        "name":baseline.get("project",{}).get("name"),
        "brief":baseline.get("project",{}).get("brief"),
        "lifecycle_stage":baseline.get("project",{}).get("lifecycle_stage"),
        "criticality":baseline.get("project",{}).get("criticality"),
      },
      "engineering_gate":gate,
      "baseline_state":baseline.get("status",{}).get("baseline_state"),
      "contexts":profile.get("contexts",[]),
      "material_contexts_to_confirm":material_candidates,
      "top_findings":a.get("findings",[])[:8],
      "current_task":runtime.get("current_task"),
      "last_verification":runtime.get("last_verification"),
      "last_release_check":runtime.get("last_release_check"),
      "agent_next_actions":[
        "Read the baseline/profile before modifying code.",
        "If this is a non-trivial user task, run `python3 .sef/sef.py plan . --request \"<exact user request>\" --save` before implementation.",
        "Resolve only authoritative project/business questions with the user; infer routine engineering controls yourself.",
        "Before DONE run `python3 .sef/sef.py verify . --base HEAD --run`.",
        "Before production run `python3 .sef/sef.py release .`."
      ]
    }

# ---------- confirmations / intake ----------
def confirm_context(repo,context,value,reason=""):
    repo=Path(repo).resolve(); context=context.upper(); yes=str(value).lower() in {"yes","true","1","y","on"}
    pp=repo/".sef/project-profile.json"; profile=_load_json(pp,{})
    decisions=profile.setdefault("context_decisions",{})
    decisions[context]={"value":yes,"reason":reason,"decided_at":_now()}
    ctx=set(profile.get("contexts",[]))
    if yes: ctx.add(context)
    else: ctx.discard(context)
    profile["contexts"]=sorted(ctx)
    profile["context_candidates"]=[c for c in profile.get("context_candidates",[]) if c.get("context")!=context]
    _write_json(pp,profile)
    baseline=_load_json(repo/".sef/project-baseline.json",{})
    disc=baseline.setdefault("discovery",{})
    disc["context_confirmations_needed"]=[x for x in disc.get("context_confirmations_needed",[]) if x!=context]
    baseline.setdefault("architecture",{})["contexts"]=profile["contexts"]
    baseline["updated_at"]=_now(); _write_json(repo/".sef/project-baseline.json",baseline)
    return {"status":"PASS","context":context,"confirmed":yes,"reason":reason,"remaining_candidates":[c.get("context") for c in profile.get("context_candidates",[])]}

def intake(repo,brief=None,answers_file=None):
    repo=Path(repo).resolve(); path=repo/".sef/project-baseline.json"; baseline=_load_json(path,{})
    if not baseline: return {"status":"BLOCKED","reason":"NO_BASELINE","next":"run init/adopt first"}
    if brief is not None: baseline.setdefault("project",{})["brief"]=brief.strip()
    if answers_file:
        patch=_load_json(Path(answers_file),{})
        baseline=_deep_merge(baseline,patch)
    # Clear standard unknowns if corresponding baseline fields have been supplied.
    p=baseline.setdefault("project",{}); disc=baseline.setdefault("discovery",{}); unknowns=[]
    for u in disc.get("unknowns",[]):
        uid=u.get("id")
        resolved=False
        if uid=="PRODUCT_BRIEF" and p.get("brief"): resolved=True
        elif uid=="USERS_STAKEHOLDERS" and (p.get("users") or p.get("stakeholders")): resolved=True
        elif uid=="CRITICALITY" and p.get("criticality") not in {None,"","STANDARD","UNKNOWN"}: resolved=True
        elif uid=="PRODUCTION_MODEL" and baseline.get("engineering_strategy",{}).get("release_strategy_details"): resolved=True
        elif uid=="DATA_CLASSIFICATION" and baseline.get("data_classification"): resolved=True
        if not resolved: unknowns.append(u)
    disc["unknowns"]=unknowns
    confirmations=disc.get("context_confirmations_needed",[])
    if p.get("brief"):
        state="READY_FOR_TASK_PLANNING" if not unknowns and not confirmations else "READY_WITH_OPEN_QUESTIONS"
    else: state="NEEDS_DISCOVERY"
    baseline.setdefault("status",{})["baseline_state"]=state
    baseline["status"]["open_question_count"]=len(unknowns)+len(confirmations)
    baseline["updated_at"]=_now(); _write_json(path,baseline)
    return {"status":"PASS","baseline_state":state,"open_questions":baseline["status"]["open_question_count"],"baseline":baseline}

# ---------- audit / status ----------
def audit(repo,ci=False):
    repo=Path(repo).resolve(); findings=[]; profile=_load_json(repo/".sef/project-profile.json",{}); baseline=_load_json(repo/".sef/project-baseline.json",{})
    if not profile: findings.append({"severity":"BLOCKER","id":"PROFILE_MISSING","message":"Project profile missing."})
    if not baseline: findings.append({"severity":"BLOCKER","id":"BASELINE_MISSING","message":"Project Engineering Baseline missing."})
    else:
        if not baseline.get("project",{}).get("brief"): findings.append({"severity":"HIGH","id":"BRIEF_MISSING","message":"Product/project brief is not defined."})
        for u in baseline.get("discovery",{}).get("unknowns",[]): findings.append({"severity":"MEDIUM","id":"OPEN_"+str(u.get("id")),"message":u.get("question")})
    seen_context_findings=set()
    for c in profile.get("context_candidates",[]):
        ctx=c.get("context")
        sev="HIGH" if ctx in MATERIAL_CONFIRMATIONS else "MEDIUM"
        findings.append({"severity":sev,"id":"CONTEXT_UNCONFIRMED_"+str(ctx),"message":f"Context {ctx} remains unconfirmed: {c.get('evidence')}"})
        seen_context_findings.add(ctx)
    for ctx in baseline.get("discovery",{}).get("context_confirmations_needed",[]) if baseline else []:
        if ctx in seen_context_findings: continue
        sev="HIGH" if ctx in MATERIAL_CONFIRMATIONS else "MEDIUM"
        findings.append({"severity":sev,"id":"CONTEXT_UNCONFIRMED_"+str(ctx),"message":f"Context {ctx} was inferred from the project brief and requires authoritative confirmation."})
        seen_context_findings.add(ctx)
    command_sets=profile.get("command_sets",[])
    if not command_sets and not any(profile.get("commands",{}).values()): findings.append({"severity":"MEDIUM","id":"VERIFICATION_COMMANDS_UNKNOWN","message":"No build/lint/type/test commands were detected; verification strategy needs project-specific commands."})
    if not _is_git(repo): findings.append({"severity":"HIGH","id":"NOT_GIT_REPO","message":"Project is not under detectable Git version control."})
    if (repo/".github").exists() and not (repo/".github/workflows/sef-policy.yml").exists(): findings.append({"severity":"LOW","id":"SEF_CI_NOT_CONFIGURED","message":"SEF GitHub policy workflow is not configured (optional until governance is adopted)."})
    rank={"BLOCKER":4,"HIGH":3,"MEDIUM":2,"LOW":1}
    blockers=[f for f in findings if f["severity"]=="BLOCKER"]
    highs=[f for f in findings if f["severity"]=="HIGH"]
    readiness="BLOCKED" if blockers else ("NEEDS_DECISIONS" if highs else ("READY_WITH_GAPS" if findings else "READY"))
    if baseline:
        runtime=_load_json(_state_path(repo),{})
        runtime["last_audit"]={"at":_now(),"readiness":readiness,"finding_count":len(findings)}
        runtime["updated_at"]=_now()
        _write_json(_state_path(repo),runtime)
    return {"status":"PASS" if not blockers else "FAIL","project_readiness":readiness,"findings":sorted(findings,key=lambda x:-rank[x["severity"]]),"contexts":profile.get("contexts",[]),"candidates":profile.get("context_candidates",[]),"baseline_state":baseline.get("status",{}).get("baseline_state") if baseline else None}

def project_status(repo):
    repo=Path(repo).resolve(); profile=_load_json(repo/".sef/project-profile.json",{}); baseline=_load_json(repo/".sef/project-baseline.json",{}); state=_load_json(_state_path(repo),{})
    a=audit(repo)
    unconfirmed=sorted(set(
        [c.get("context") for c in profile.get("context_candidates",[]) if c.get("context")]
        + baseline.get("discovery",{}).get("context_confirmations_needed",[])
    ))
    return {"status":"PASS" if a.get("status")!="FAIL" else "NEEDS_ATTENTION","project":baseline.get("project",{}),"baseline_state":baseline.get("status",{}).get("baseline_state"),"readiness":a.get("project_readiness"),"contexts":profile.get("contexts",[]),"unconfirmed_contexts":unconfirmed,"current_task":state.get("current_task"),"last_verification":state.get("last_verification"),"last_release_check":state.get("last_release_check"),"top_findings":a.get("findings",[])[:8]}


# ---------- RC-1 deterministic concept normalization ----------
# RC1_CONCEPT_NORMALIZATION_ADDITIVE_V1
# This layer normalizes bounded request-language variants into six canonical
# concepts. It is additive: it may add request routing signals, never remove or
# downgrade legacy routing, and actual-diff reassessment remains independent.
def _rc1_normalize_text(text):
    import unicodedata
    text=unicodedata.normalize("NFKC",str(text or ""))
    text=text.replace("’","'").replace("‘","'").replace("‐","-").replace("‑","-").replace("–","-")
    return re.sub(r"\s+"," ",text).strip().lower()

_RC1_CONCEPT_RULES=(
  ("AUTHORIZATION","pack","AUTHORIZATION",(
    r"\b(?:permission|permissions|rbac|access control|authorization|authorisation)\b",
    r"\b(?:authorized|authorised)\s+(?:administrator|admin|user|operator|person|role)\b",
    r"\bonly\s+(?:an?\s+)?(?:authorized|authorised)\s+(?:administrator|admin|user|operator|person|role)\b",
  )),
  ("DATABASE_MIGRATION","pack","DATABASE_MIGRATION",(
    r"\bdatabase\s+migration\b",
    r"\bmigrat(?:e|es|ed|ing)\b.{0,80}\b(?:existing|stored|records?|rows?|timestamps?|data|database)\b",
    r"\b(?:existing|stored|records?|rows?|timestamps?|data|database)\b.{0,80}\bmigrat(?:e|es|ed|ing)\b",
  )),
  ("WEBHOOK_TRUST","pack","WEBHOOK_TRUST",(
    r"\bwebhook(?:s)?\b.{0,100}\b(?:receive|receives|received|accept|accepts|inbound|event|events|provider|callback)\b",
    r"\b(?:receive|receives|accept|accepts|inbound)\b.{0,100}\bwebhook(?:s)?\b",
    r"\bprovider\s+webhook(?:s)?\b",
  )),
  ("EXTERNAL_SUPPLIER","pack","EXTERNAL_SUPPLIER",(
    r"\bexternal\s+api\b.{0,100}\b(?:supplied|provided|provider|vendor|third-party|third party)\b",
    r"\b(?:third-party|third party|external)\s+(?:saas\s+)?(?:vendor|provider|supplier|service|api)\b",
    r"\bdepend(?:s|ed|ing)?\s+on\b.{0,80}\b(?:third-party|third party|external)\b",
  )),
  ("BACKGROUND_JOB","execution_context","BACKGROUND_JOB",(
    r"\bqueue\s+consumer\b.{0,100}\b(?:job|jobs|async|asynchronously|retry|retries|retryable)\b",
    r"\bqueue\s+worker\b.{0,100}\b(?:job|jobs|async|asynchronously|retry|retries|retryable|failed)\b",
    r"\b(?:retryable\s+)?background\s+worker\b",
    r"\bworker\b.{0,100}\b(?:process|processes|processing|run|runs|running)\b.{0,80}\b(?:job|jobs|task|tasks)\b",
    r"\bworker\b.{0,100}\b(?:job|jobs)\b.{0,80}\b(?:background|async|asynchronously|retry|retries|retryable)\b",
  )),
  ("SEO_WEB_DISCOVERABILITY","execution_context","SEO_WEB_DISCOVERABILITY",(
    r"\bseo\b.{0,120}\b(?:public|page|search engine|index|indexing|indexation|crawl|discover)\b",
    r"\b(?:public\s+)?(?:product\s+)?page\b.{0,120}\b(?:search engines?|search engine)\b.{0,80}\b(?:find|index|discover|crawl)\w*\b",
    r"\b(?:find|discover)\w*\b.{0,80}\bthrough\s+search\s+engines?\b",
    r"\b(?:find|discover)\w*\b.{0,100}\bpublic\b.{0,80}\bpage\b.{0,120}\bsearch\s+engines?\b",
    r"\bdiscoverable\s+(?:in|through|via)\s+search\b",
  )),
)

def _rc1_detect_concepts(request):
    normalized=_rc1_normalize_text(request); observations=[]
    for concept,output_kind,output_id,patterns in _RC1_CONCEPT_RULES:
        matches=[]
        for pattern in patterns:
            m=re.search(pattern,normalized,re.I)
            if m: matches.append({"pattern":pattern,"match":m.group(0),"span":[m.start(),m.end()]})
        if matches:
            observations.append({"concept":concept,"candidate_output":{"kind":output_kind,"id":output_id},"evidence":matches})
    return observations

def _rc1_detected_ids(request):
    return {str(x.get("concept")) for x in _rc1_detect_concepts(request)}

def _rc1_stateful_database_companion(request):
    text=_rc1_normalize_text(request)
    return re.search(r"\bdatabase\b|\bledger\s+state\b|\bwrite(?:s|ing)?\b.{0,50}\b(?:ledger|state|record|records|row|rows|database)\b",text,re.I) is not None


# ---------- RC-2 request polarity / bounded non-goals ----------
_RC2_BOUNDARY_RE=re.compile(r"\s*(?:[;.!?]+|\bbut\b|\bmais\b)\s*",re.I)
_RC2_NON_GOAL_PATTERNS=(
  ("do_not_change",re.compile(r"\b(?:do not|don't)\s+(?:change|modify|touch)\b",re.I)),
  ("without_change",re.compile(r"\bwithout\s+(?:changing|modifying|touching)\b",re.I)),
  ("leave_unchanged",re.compile(r"\b(?:leave|keep)\b.+?\bunchanged\b",re.I)),
  ("no_changes_to",re.compile(r"\bno\s+changes?\s+to\b",re.I)),
  ("no_modifications_to",re.compile(r"\bno\s+modifications?\s+to\b",re.I)),
  ("out_of_scope",re.compile(r"\b(?:out of scope|not in scope)\b",re.I)),
  ("fr_sans_changer",re.compile(r"\bsans\s+(?:changer|modifier|toucher)\b",re.I)),
  ("fr_unchanged",re.compile(r"\b(?:laisser|garder)\b.+?\binchang[ée]s?\b",re.I)),
  ("fr_no_change",re.compile(r"\baucun\s+changement\b",re.I)),
  ("fr_out_of_scope",re.compile(r"\bhors\s+p[ée]rim[èe]tre\b",re.I)),
)
_RC2_POSITIVE_GUARDS=(
  ("do_not_forget",re.compile(r"\b(?:do not|don't)\s+forget\b",re.I)),
  ("cannot_leave_unchanged",re.compile(r"\bcannot\s+(?:leave|keep)\b.+?\bunchanged\b",re.I)),
  ("prohibitive_requirement",re.compile(r"\b(?:must not|cannot|may not)\b",re.I)),
  ("no_actor_may",re.compile(r"\bno\s+.+?\bmay\b",re.I)),
  ("without_is_unsafe",re.compile(r"\bwithout\b.+?\b(?:unsafe|insecure|vulnerable)\b",re.I)),
)

def _rc2_clauses(text):
    out=[]; start=0
    for m in _RC2_BOUNDARY_RE.finditer(str(text or "")):
        chunk=str(text or "")[start:m.start()].strip(" ,")
        if chunk: out.append((start,m.start(),chunk))
        start=m.end()
    raw=str(text or ""); chunk=raw[start:].strip(" ,")
    if chunk: out.append((start,len(raw),chunk))
    return out

def _rc2_annotate(request):
    observations=[]
    for start,end,clause in _rc2_clauses(request):
        guards=[name for name,rx in _RC2_POSITIVE_GUARDS if rx.search(clause)]
        matches=[]
        if not guards:
            for name,rx in _RC2_NON_GOAL_PATTERNS:
                m=rx.search(clause)
                if m: matches.append({"cue":name,"span":[start+m.start(),start+m.end()],"text":m.group(0)})
        polarity="NON_GOAL" if matches else ("POSITIVE_GUARD" if guards else "UNMARKED")
        observations.append({"span":[start,end],"clause":clause,"polarity":polarity,"cues":matches,"guards":guards})
    return {"request":request,"clauses":observations,"shadow_only":False}

def _rc2_positive_request_text(request):
    observation=_rc2_annotate(request); kept=[]; suppressed=[]
    for clause in observation.get("clauses",[]):
        value=str(clause.get("clause") or "").strip()
        if not value: continue
        if clause.get("polarity")=="NON_GOAL": suppressed.append(value)
        else: kept.append(value)
    return "; ".join(kept),suppressed,observation

# ---------- request → engineering task plan ----------
def _request_change(profile,request):
    original_request=request
    request,rc2_suppressed,rc2_observation=_rc2_positive_request_text(request)
    t=request.lower(); triggers=set(); contexts=set(profile.get("contexts",[])); task_contexts=set(); profiles=set(profile.get("profiles",[])); evidence=[]
    def hit(pattern): return re.search(pattern,t,re.I) is not None
    def add(trg,why,ctx=(),prof=()): triggers.add(trg); contexts.update(ctx); task_contexts.update(ctx); profiles.update(prof); evidence.append({"trigger":trg,"reason":why})
    if hit(r"\b(oauth|oidc|openid|google login|connexion google|sign[ -]?in|log[ -]?in|login|connexion|authentification|authentication|session|jwt)\b"):
        add("AUTH_CHANGED","authentication/login semantics in request",["PUBLIC_API"])
        add("SESSION_TOKEN_CHANGED","session/token semantics likely affected")
        if hit(r"\b(oauth|oidc|openid|google)\b"):
            profiles.update(["OAUTH_CLIENT","OIDC_CLIENT","SESSION"]); contexts.add("PII")
    if hit(r"\b(permission|permissions|rôle|rôles|role|roles|rbac|authori[sz]|autorisation|admin|propriétaire|owner|contrôle d.access|access control)\b"): add("AUTHZ_CHANGED","authorization/role semantics in request")
    if hit(r"\b(multi[- ]?tenant|multi[- ]?locataire|isolation tenant|tenant isolation|cross[- ]tenant|inter[- ]tenant|workspace isolation)\b"): add("TENANT_BOUNDARY_CHANGED","explicit tenant isolation change",["MULTI_TENANT"])
    if hit(r"\b(upload|téléversement|televersement|pièce jointe|piece jointe|attachment|import fichier|file import|document upload)\b"): add("FILE_UPLOAD_ADDED","file upload surface requested",["FILE_UPLOAD"])
    if hit(r"\b(webhook|callback|endpoint de rappel|callback endpoint)\b"): add("INBOUND_WEBHOOK_ADDED","inbound webhook/callback requested",["INBOUND_WEBHOOK","PUBLIC_API"])
    if hit(r"\b(migration|schéma|schema|colonne|column|table|base de données|database change|backfill|rattrapage de données)\b"): add("DATABASE_SCHEMA_CHANGED","database/schema change requested",["DATABASE"])
    if hit(r"\b(drop|truncate|supprimer les données|suppression de données|delete data|supprimer colonne|remove column|détruire les données|destroy data)\b"): add("DESTRUCTIVE_DATA_CHANGE","destructive data semantics requested",["DATABASE"])
    if hit(r"\b(docker|container|compose)\b"): add("DOCKERFILE_CHANGED","containerization change requested",["DOCKER"])
    if hit(r"\b(github actions|ci/cd|pipeline|intégration continue|integration continue|continuous integration)\b"): add("CI_WORKFLOW_CHANGED","CI/CD change requested",["CI_CD"])
    if hit(r"\b(terraform|iac|infrastructure as code|infrastructure comme code|security group|groupe de sécurité|firewall|pare-feu|vpc|subnet|sous-réseau)\b"): add("IAC_CHANGED","infrastructure/IaC change requested",["IAC"])
    if hit(r"\b(public ingress|0\.0\.0\.0/0|open to internet|publicly accessible)\b"): add("NETWORK_EXPOSURE_CHANGED","network exposure change requested",["NETWORK_EXPOSURE"])

    # Web discoverability execution domains are task-scoped playbooks, not new canonical policy contexts.
    public_marketing_site = hit(r"\b(site web|website|site internet|site vitrine|site web d['’]entreprise|site d['’]entreprise|marketing site|corporate (?:web)?site|business website|public website|landing page|page d['’]atterrissage|site institutionnel)\b") and not hit(r"\b(intranet|internal website|site interne|admin portal|portail admin)\b")
    lead_generation = hit(r"\b(génér(?:er|ation).*leads?|generation.*leads?|lead generation|acquisition organique|organic acquisition|prospects?|conversion rate|taux de conversion)\b")
    seo_scope = hit(r"\b(seo|référencement(?: naturel)?|referencement(?: naturel)?|search engine optimization|organic search|recherche organique|indexation|crawl(?:ing)?|sitemap|robots\.txt|canonical|canonique|schema\.org|structured data|données structurées|donnees structurees|search console|core web vitals?)\b")
    ai_discoverability_scope = hit(r"\b(generative engine optimization|answer engine optimization|geo|aeo|ai discoverability|discoverability ai|visibilité ia|visibilite ia|recherche ia|ai search|chatgpt search|google ai overviews?|ai mode|answer engine|moteur de réponse|moteur de reponse|oai-searchbot|gptbot|llms\.txt)\b")
    analytics_scope = hit(r"\b(google analytics|ga4|google tag manager|gtm|tag manager|web analytics|product analytics|analytics tracking|event tracking|suivi des événements|suivi des evenements|conversion tracking|suivi des conversions|funnel analytics|attribution|utm_(?:source|medium|campaign|content|term)|dataLayer|measurement protocol|tracking pixel|pixel de suivi|plausible analytics|posthog|mixpanel|segment analytics)\b")
    visual_only_scope = hit(r"\b(css|spacing|espacement|color|couleur|font|police|typograph|style only|style uniquement|visual tweak|modification visuelle)\b") and not (seo_scope or ai_discoverability_scope or analytics_scope or lead_generation)
    public_site_foundation_scope = public_marketing_site and not visual_only_scope and (
        lead_generation
        or hit(r"\b(crée|creer|créer|create|build|construire|lancer|launch|refonte|redesign|rebuild|nouveau site|new website|je veux|j['’]aimerais|i want|landing page|page d['’]atterrissage|architecture|arborescence|contenu|content|blog|article|navigation|route|url|metadata|métadonnées|metadonnees)\b")
    )
    if public_marketing_site:
        contexts.add("WEB_UI"); task_contexts.add("WEB_UI")
    if public_site_foundation_scope or seo_scope:
        task_contexts.add("SEO_WEB_DISCOVERABILITY")
        evidence.append({"trigger":"SEO_WEB_DISCOVERABILITY_SCOPE","reason":"public-site foundation/discoverability scope or explicit SEO scope requested"})
    if ai_discoverability_scope:
        task_contexts.update(["SEO_WEB_DISCOVERABILITY","AI_DISCOVERABILITY"])
        evidence.append({"trigger":"AI_DISCOVERABILITY_SCOPE","reason":"generative/answer-engine discoverability requested"})
    if analytics_scope or (public_marketing_site and lead_generation):
        task_contexts.add("ANALYTICS_CONVERSION")
        evidence.append({"trigger":"ANALYTICS_CONVERSION_SCOPE","reason":"measurement/conversion instrumentation requested or implied by lead-generation outcome"})

    # Avoid misrouting pure AI-search/GEO requests into the AI-system runtime pack.
    ai_runtime_specific = hit(r"\b(llm|rag|mcp|tool calling|agentic|autonomous agent|prompt(?:ing)?|embedding|vector database|inference|fine[- ]?tun|model serving|openai api|anthropic api|gemini api)\b") or hit(r"\b(modèle|model)\s+(ia|ai|llm|génératif|generative|language)\b|\b(language|foundation)\s+model\b")
    broad_ai = hit(r"\b(ai|ia|agent|openai|anthropic|gemini)\b")
    if ai_runtime_specific or (broad_ai and not ai_discoverability_scope): add("AI_COMPONENT_CHANGED","AI/model/agent component requested",["AI_LLM"])
    if hit(r"\b(agent|tool calling|mcp|autonomous|execute commands)\b") and not (ai_discoverability_scope and not ai_runtime_specific): contexts.add("AGENTIC_RUNTIME"); task_contexts.add("AGENTIC_RUNTIME")
    if hit(r"\b(performance|latence|latency|débit|throughput|scale|scalabilité|scalability|capacité|capacity|test de charge|load test|optimi[sz]|optimis)\b"): add("PERFORMANCE_SENSITIVE_PATH_CHANGED","performance/capacity goal in request")
    if hit(r"\b(timezone|fuseau horaire|fuseaux horaires|dst|heure d.été|schedule|planning|planification|réservation planifiée|expiry|expiration|expiration|cron|date/time|date et heure)\b"): add("TIME_LOGIC_CHANGED","time/scheduling semantics in request")
    if hit(r"\b(dependency|dépendance|dependance|package|paquet|library|bibliothèque|upgrade framework|mettre à jour.*framework|update package)\b"): add("DEPENDENCY_UPDATED","dependency lifecycle change requested")
    if hit(r"\b(release|livraison|déployer|deployer|deploy|déploiement|deploiement|deployment|production|mise en production|go live)\b"): add("RELEASE_PREPARED","release/deployment requested")
    if hit(r"\b(deploy to production|déployer en production|deployer en production|mise en production|production deploy|go live)\b"): add("PRODUCTION_DEPLOY","production deployment requested",["PRODUCTION"])
    if hit(r"\b(personal data|données personnelles|donnees personnelles|pii|gdpr|rgpd|privacy|vie privée|email address|adresse email|phone number|numéro de téléphone|numero de telephone)\b"): add("PII_TOUCHED","personal-data handling explicitly requested",["PII"])
    if hit(r"\b(css|spacing|espacement|color|couleur|font|police|style only|style uniquement|visual tweak|modification visuelle)\b"): add("UI_STYLE_CHANGED","visual-only UI change requested",["WEB_UI"])
    if hit(r"\b(form|formulaire|button|bouton|modal|dialog|dialogue|navigation|interactive ui|interface interactive|frontend feature|fonctionnalité frontend|frontend|front-end|page|component|composant|dashboard|tableau de bord)\b"): add("UI_BEHAVIOR_CHANGED","interactive/frontend behavior requested",["WEB_UI"])
    if hit(r"\b(backend|back-end|api|endpoint|route api|service backend|service api|rest|graphql|rpc|controller|contrôleur|controleur)\b"):
        contexts.add("PUBLIC_API"); task_contexts.add("PUBLIC_API")
        if not triggers: evidence.append({"trigger":"BACKEND_API_SCOPE","reason":"backend/API execution scope requested"})
    if hit(r"\b(crud|modèle de données|modele de donnees|data model|entité|entite|entity|relation|foreign key|clé étrangère|cle etrangere|index|requête sql|requete sql|query|sql|orm|prisma|sqlalchemy)\b"):
        contexts.add("DATABASE"); task_contexts.add("DATABASE")
        evidence.append({"trigger":"DATABASE_DESIGN_SCOPE","reason":"database design/query execution scope requested"})
    if hit(r"\b(réservation|reservation|booking|rendez[- ]?vous|appointment|planning|planification|course|trajet)\b"):
        contexts.add("DATABASE"); task_contexts.add("DATABASE")
        if not any(x in triggers for x in {"DATABASE_SCHEMA_CHANGED","TIME_LOGIC_CHANGED"}): evidence.append({"trigger":"DOMAIN_BOOKING","reason":"booking/scheduling domain implies data-state/concurrency review"})
    if hit(r"\b(full[- ]?stack|de bout en bout|end[- ]to[- ]end|frontend.*backend|front.*back)\b"):
        for ctx in ("WEB_UI","PUBLIC_API","DATABASE"):
            if ctx in contexts or ctx in profile.get("contexts",[]): task_contexts.add(ctx)
        evidence.append({"trigger":"FULL_STACK_SCOPE","reason":"explicit cross-layer application scope requested"})
    if "UI_STYLE_CHANGED" in triggers and "UI_BEHAVIOR_CHANGED" in triggers and hit(r"\b(uniquement|seulement|only|purely|juste|just)\b"):
        substantive=triggers-{"UI_STYLE_CHANGED","UI_BEHAVIOR_CHANGED"}
        if not substantive: triggers.discard("UI_BEHAVIOR_CHANGED")
    if not triggers: triggers.add("NEW_FEATURE" if hit(r"\b(add|ajouter|ajoute|create|créer|creer|implement|implémenter|implementer|build|construire|feature|fonctionnalité|new|nouveau|nouvelle)\b") else "BUSINESS_LOGIC_CHANGED")

    # RC-1 additive compatibility adapter. Legacy request signals above remain
    # untouched; canonical concepts may only add missing triggers/contexts.
    rc1_observations=_rc1_detect_concepts(request)
    for observation in rc1_observations:
        concept=str(observation.get("concept") or "")
        if concept=="AUTHORIZATION": triggers.add("AUTHZ_CHANGED")
        elif concept=="DATABASE_MIGRATION":
            triggers.add("DATABASE_SCHEMA_CHANGED"); contexts.add("DATABASE"); task_contexts.add("DATABASE")
        elif concept=="WEBHOOK_TRUST":
            triggers.add("INBOUND_WEBHOOK_ADDED"); contexts.update(["INBOUND_WEBHOOK","PUBLIC_API"]); task_contexts.update(["INBOUND_WEBHOOK","PUBLIC_API"])
        elif concept=="EXTERNAL_SUPPLIER":
            contexts.add("EXTERNAL_SAAS"); task_contexts.add("EXTERNAL_SAAS")
        elif concept=="BACKGROUND_JOB":
            contexts.add("BACKGROUND_JOB"); task_contexts.add("BACKGROUND_JOB")
            if _rc1_stateful_database_companion(request): contexts.add("DATABASE"); task_contexts.add("DATABASE")
        elif concept=="SEO_WEB_DISCOVERABILITY": task_contexts.add("SEO_WEB_DISCOVERABILITY")
        else: continue
        evidence.append({"trigger":"RC1_CONCEPT:"+concept,"reason":"deterministic canonical concept detected","source":"rc1_additive","concept_evidence":observation.get("evidence",[])})
    if rc2_suppressed:
        evidence.append({"trigger":"RC2_POLARITY_FILTER","reason":"bounded request non-goal excluded from request-derived routing","source":"rc2_canonical","suppressed_clauses":rc2_suppressed,"polarity_observation":rc2_observation})
    risk="R0" if triggers=={"UI_STYLE_CHANGED"} else "R1"
    # Generic new product features in an already full-stack repository may reasonably cross layers;
    # bugs/refactors without layer evidence stay on core procedures until inspection/diff reveals scope.
    if not task_contexts and "NEW_FEATURE" in triggers:
        app=[c for c in ("WEB_UI","PUBLIC_API","DATABASE") if c in contexts]
        if len(app)>=2: task_contexts.update(app)
    return {"summary":original_request,"risk":risk,"action_class":"A1","contexts":sorted(contexts),"execution_contexts":sorted(task_contexts),"triggers":sorted(triggers),"profiles":sorted(profiles),"environment":"LOCAL","request_detection":evidence}

def _assess_request(repo,request):
    repo=Path(repo).resolve(); profile=_load_json(repo/".sef/project-profile.json",scan(repo)); change=_request_change(profile,request)
    td,root=_runtime_root()
    try:
        b=_load_bootstrap(root); module=b.load_sef_module(repo)
        matrix=module.load_json(root/".sef/policy/master-control-matrix.json")
        ontology=module.load_json(root/".sef/policy/ontology.json")
        packs=module.load_json(root/".sef/packs.json")
        normalized=module.normalize_change(change,profile,ontology,[])
        result=module.assess_workflow(matrix,normalized,packs)

        # RC-1 compatibility: v1.4 has an EXTERNAL_SUPPLIER pack but no request
        # trigger selecting it from EXTERNAL_SAAS alone.
        rc2_positive_request,_,_=_rc2_positive_request_text(request)
        if "EXTERNAL_SUPPLIER" in _rc1_detected_ids(rc2_positive_request):
            selected=set(result.get("required_context_packs",[])); selected.add("EXTERNAL_SUPPLIER")
            result["required_context_packs"]=sorted(selected)
        result["request_detection"]=change["request_detection"]
        result["request_execution_contexts"]=change.get("execution_contexts",[])
        return result
    finally: td.cleanup()

def _implicit_requirements(request,assessment,baseline):
    packs=set(assessment.get("required_context_packs",[])); req=[]
    req += ["Clarify acceptance criteria and non-goals before broad implementation.","Preserve existing architecture/scope unless a deliberate decision changes them.","Reclassify the actual diff after implementation; planned risk is provisional."]
    by={
      "AUTH_PROTOCOL":["Define identity/session lifecycle, failure/recovery paths and protocol invariants; verify negative auth cases."],
      "AUTHORIZATION":["Define server-side function/object/field authorization and a negative permission matrix."],
      "MULTI_TENANT":["Prove tenant scope at data/cache/job/storage/search boundaries and cross-tenant denial paths."],
      "DATABASE_MIGRATION":["Define migration compatibility, rollout ordering, lock/load implications, reconciliation and rollback/roll-forward semantics."],
      "RECOVERY":["Prove recovery/restore for destructive or high-impact data changes before production execution."],
      "FILE_UPLOAD_SECURITY":["Treat files as hostile input: type/content/size/storage/parser/auth/quota controls."],
      "WEBHOOK_TRUST":["Verify origin/integrity, replay/duplicate handling, schema validation and local authorization before side effects."],
      "CONTAINER_ENGINEERING":["Keep build/runtime separation, secrets, privileges, health/persistence and immutable image identity controlled."],
      "CI_SUPPLY_CHAIN":["Protect untrusted code boundaries, workflow permissions, dependencies and release provenance."],
      "INFRASTRUCTURE_IAC":["Review exact infrastructure plan, state/secrets, network exposure, destructive replacement and operator recovery."],
      "AI_SYSTEM":["Define model/tool/data authority, prompt-injection boundaries, sandbox/network/credentials, evaluations and cost/failure limits."],
      "PRIVACY":["Minimize personal data, define purpose/retention/access/sharing and route high-risk privacy decisions to qualified review."],
      "PERFORMANCE_CAPACITY_COST":["Define measurable budgets, representative load/capacity evidence and saturation/cost guardrails."],
      "UI_ACCESSIBILITY_COMPAT":["Define applicable accessibility/support matrix and verify critical journeys beyond one developer browser."],
      "TIME_SEMANTICS":["Define instant/local-time/timezone/DST/expiry/precision semantics explicitly and test boundaries."],
      "RELEASE_ENGINEERING":["Require exact release identity, staged/observable rollout when warranted, rollback/containment and post-deploy checks."],
      "MAINTENANCE_VULNERABILITY":["Define ownership, remediation/upgrade impact and recurrence-prevention evidence."],
      "EXTERNAL_SUPPLIER":["Define supplier ownership, data/access/quota/failure/exit/deprecation implications."],
      "REGULATED_DOMAIN":["Identify applicable jurisdiction/domain overlay and qualified authority before compliance/safety claims."],
    }
    for p in sorted(packs): req += by.get(p,[])
    exec_ctx=set(assessment.get("request_execution_contexts",[]))
    if "SEO_WEB_DISCOVERABILITY" in exec_ctx:
        req += ["Define intentional crawl/indexation/canonical/sitemap behavior for public routes; technical readiness must not be represented as guaranteed ranking or traffic.","Use external search data for demand/performance claims; do not fabricate keyword volume, rankings or indexation evidence."]
    if "AI_DISCOVERABILITY" in exec_ctx:
        req += ["Separate AI-search crawler access from model-training crawler policy; verify current provider guidance and do not treat experimental GEO conventions as standards.","Use observable crawl/referral/citation evidence and explicitly state that generative-search placement/citation is not guaranteed."]
    if "ANALYTICS_CONVERSION" in exec_ctx:
        req += ["Define a measurement plan and event/conversion contract before adding tags; verify implementation, transport, provider ingestion and conversion semantics separately.","Prevent PII/secrets from entering analytics payloads and assess consent/privacy applicability before production tracking."]
    return list(dict.fromkeys(req))

def task_plan(repo,request,save=False):
    repo=Path(repo).resolve(); baseline=_load_json(repo/".sef/project-baseline.json",{}); assessment=_assess_request(repo,request)
    risk=assessment.get("risk","R1"); packs=assessment.get("required_context_packs",[])
    req=_implicit_requirements(request,assessment,baseline)
    dod=[
      "Explicit task acceptance criteria satisfied without unrelated changes.",
      "Architecture/data/API/security implications from the plan are addressed or deliberately recorded.",
      "Required specialist procedures are applied for routed packs.",
      "Direct project verification passes; unavailable required evidence remains NOT_VERIFIED.",
      "Actual diff is re-assessed and does not reveal unhandled higher risk.",
      "Known residual risk and follow-up debt are explicit rather than hidden."
    ]
    if RISK_ORDER.get(risk,1)>=3: dod += ["Independent/machine evidence is present for hard specialist gates; agent observation alone is insufficient."]
    if "RELEASE_ENGINEERING" in packs or "PRODUCTION" in assessment.get("contexts",[]): dod += ["Exact release revision/artifact and rollback/roll-forward strategy are identified before production eligibility."]
    execution_contexts=assessment.get("request_execution_contexts",[])
    if "SEO_WEB_DISCOVERABILITY" in execution_contexts: dod += ["Indexability/crawl/canonical/sitemap/metadata behavior is intentional and verified for material public routes; search ranking/indexation claims use external evidence."]
    if "AI_DISCOVERABILITY" in execution_contexts: dod += ["AI-search crawler/training-crawler policy is explicit; citation readiness is verified without promising provider placement."]
    if "ANALYTICS_CONVERSION" in execution_contexts: dod += ["Measurement contract is defined; critical conversion instrumentation is verified beyond tag firing, including ingestion and duplicate/failure semantics where applicable."]
    architecture_questions=[]
    if set(packs)&{"DATABASE_MIGRATION","MULTI_TENANT","INFRASTRUCTURE_IAC","AUTH_PROTOCOL","AI_SYSTEM"}: architecture_questions.append("Does this change alter trust/data/tenant/infrastructure boundaries or require an architecture decision record in the baseline?")
    if "EXTERNAL_SUPPLIER" in packs: architecture_questions.append("Does this introduce lock-in, data transfer, credentials, quota or new failure dependencies?")
    if "SEO_WEB_DISCOVERABILITY" in execution_contexts: architecture_questions.append("Which routes are intentionally public/indexable versus private/noindex, and what user/search intents should the public information architecture satisfy?")
    if "AI_DISCOVERABILITY" in execution_contexts: architecture_questions.append("Which AI/search providers matter, and what is the intended policy for search discovery versus model-training crawlers?")
    if "ANALYTICS_CONVERSION" in execution_contexts: architecture_questions.append("What business outcomes count as conversions, which system is authoritative for each, and what analytics/privacy constraints apply?")
    procedures=list(CORE_SKILLS)+[ROUTE_TO_SKILL[p] for p in packs if p in ROUTE_TO_SKILL]
    procedures+=_execution_skills(execution_contexts,assessment.get("triggers",[]),risk,packs)
    project_profile=_load_json(repo/".sef/project-profile.json",{})
    human_decisions=sorted(set(
        [c.get("context") for c in project_profile.get("context_candidates",[]) if c.get("context") in MATERIAL_CONFIRMATIONS]
        + [ctx for ctx in baseline.get("discovery",{}).get("context_confirmations_needed",[]) if ctx in MATERIAL_CONFIRMATIONS]
    ))
    plan={
      "task_id":"task-"+dt.datetime.now().strftime("%Y%m%d-%H%M%S"),"created_at":_now(),"request":request,
      "project_baseline_state":baseline.get("status",{}).get("baseline_state"),
      "assessment":{"risk":risk,"action_class":assessment.get("action_class"),"action_policy":assessment.get("action_policy"),"contexts":assessment.get("contexts",[]),"execution_contexts":execution_contexts,"triggers":assessment.get("triggers",[]),"profiles":assessment.get("profiles",[]),"required_packs":packs,"selected_controls":assessment.get("selected_control_count"),"specialist_controls":assessment.get("specialist_control_count")},
      "implicit_professional_requirements":req,
      "architecture_questions":architecture_questions,
      "implementation_guardrails":["Inspect existing code/architecture before editing.","Use applicable frontend/backend/database/full-stack/web-discoverability/analytics execution playbooks selected from the actual project context.","Prefer smallest coherent change that satisfies requirements.","Do not silently weaken security/recovery/governance to make tests pass.","Preserve compatibility or explicitly manage breaking change/migration.","Keep cross-layer invariants authoritative at the correct boundary: UI feedback is not backend authorization; API validation is not a database constraint."],
      "verification_strategy":["Use detected workspace lint/type/unit/build commands proportionately.","For full-stack journeys, verify contracts and behavior across frontend→API→domain→database boundaries where material.","Add regression/negative/integration/e2e/specialist evidence required by routed packs.","Re-assess actual Git diff before claiming completion."],
      "definition_of_done":dod,
      "procedures":list(dict.fromkeys(procedures)),
      "human_decisions_needed":human_decisions,
      "implementation_gate":"BLOCKED_PENDING_AUTHORITATIVE_CONTEXT" if human_decisions else "READY",
      "implementation_allowed":not bool(human_decisions),
      "state":"PLANNED"
    }
    if save:
        sp=_state_path(repo); st=_load_json(sp,{}); st["current_task"]=plan; st["updated_at"]=_now(); _write_json(sp,st)
    return {"status":"PASS","plan":plan,"saved":bool(save)}

# ---------- actual-diff execution-domain detection ----------
def _actual_web_execution_contexts(repo,assessment):
    """Detect web-growth execution domains from changed paths/content without extending canonical policy IDs."""
    repo=Path(repo).resolve(); contexts=set(); evidence=[]
    paths=[str(x) for x in assessment.get("changed_paths",[]) if x]
    seo_path=re.compile(r"(^|/)(robots\.txt|sitemap(?:[^/]*)\.(?:xml|txt)|[^/]*(?:seo|schema|structured-data|metadata|opengraph|open-graph)[^/]*)$",re.I)
    analytics_path=re.compile(r"(?:analytics|tracking|tagmanager|tag-manager|gtm|ga4|posthog|plausible|mixpanel|segment|pixel)",re.I)
    text_suffixes={".html",".htm",".md",".mdx",".js",".jsx",".ts",".tsx",".vue",".svelte",".astro",".json",".xml",".txt",".py",".rb",".php"}
    patterns={
      "SEO_WEB_DISCOVERABILITY":re.compile(r"rel=[\"']canonical|application/ld\+json|robots\.txt|noindex|x-robots-tag|sitemap|hreflang|schema\.org|search console",re.I),
      "AI_DISCOVERABILITY":re.compile(r"oai-searchbot|gptbot|chatgpt search|ai overviews?|ai mode|generative engine|answer engine|llms\.txt",re.I),
      "ANALYTICS_CONVERSION":re.compile(r"googletagmanager\.com|google-analytics\.com|gtag\s*\(|dataLayer|G-[A-Z0-9]{6,}|measurement protocol|posthog|plausible|mixpanel|segment\.(?:track|identify)|utm_source|conversion[_ -]?(?:event|tracking)",re.I),
    }
    for rel in paths:
        if seo_path.search(rel): contexts.add("SEO_WEB_DISCOVERABILITY"); evidence.append({"path":rel,"domain":"SEO_WEB_DISCOVERABILITY","signal":"path"})
        if analytics_path.search(rel): contexts.add("ANALYTICS_CONVERSION"); evidence.append({"path":rel,"domain":"ANALYTICS_CONVERSION","signal":"path"})
        fp=repo/rel
        if not fp.is_file() or fp.suffix.lower() not in text_suffixes:
            continue
        try:
            content=fp.read_text(encoding="utf-8",errors="ignore")[:131072]
        except Exception:
            continue
        for ctx,pat in patterns.items():
            if pat.search(content): contexts.add(ctx); evidence.append({"path":rel,"domain":ctx,"signal":"content"})
    if "AI_DISCOVERABILITY" in contexts: contexts.add("SEO_WEB_DISCOVERABILITY")
    return sorted(contexts),evidence[:30]

# ---------- verification ----------
def _verification_commands(profile,risk,triggers):
    desired=["lint","typecheck","unit"]
    if "DOC_ONLY_CHANGED" not in triggers: desired.append("build")
    if RISK_ORDER.get(risk,1)>=2: desired += ["integration","e2e"]
    out=[]
    sets=profile.get("command_sets",[])
    if not sets and any(profile.get("commands",{}).values()): sets=[{"path":".","manager":"unknown","commands":profile.get("commands",{})}]
    for cs in sets:
        for k in desired:
            cmd=(cs.get("commands") or {}).get(k)
            if cmd: out.append({"workspace":cs.get("path","."),"kind":k,"command":cmd})
    # dedupe
    seen=set(); res=[]
    for x in out:
        key=(x["workspace"],x["kind"],x["command"])
        if key not in seen: seen.add(key); res.append(x)
    return res

def verify(repo,base="HEAD",run_commands=False,allow_risky_exec=False):
    repo=Path(repo).resolve(); a=assess(repo,base); profile=_load_json(repo/".sef/project-profile.json",{})
    triggers=set(a.get("triggers",[])); risk=a.get("risk","R1"); planned=_verification_commands(profile,risk,triggers)
    actual_web_contexts,actual_web_evidence=_actual_web_execution_contexts(repo,a)
    actual_execution_contexts=sorted(set(a.get("contexts",[]))|set(actual_web_contexts))
    required_execution_procedures=_execution_skills(actual_execution_contexts,triggers,risk,a.get("required_context_packs",[]))
    saved_task=(_load_json(_state_path(repo),{}) or {}).get("current_task") or {}
    saved_procedures=set(saved_task.get("procedures",[]))
    newly_required_web_procedures=sorted(p for p in required_execution_procedures if p in {"seo-web-discoverability-engineering","geo-ai-discoverability-engineering","analytics-conversion-instrumentation"} and p not in saved_procedures)
    risky=bool(triggers & {"PACKAGE_SCRIPT_EXECUTION","UNTRUSTED_PR_CODE"})
    if run_commands and risky and not allow_risky_exec:
        result={"status":"BLOCKED","local_verification_state":"BLOCKED_RISKY_EXECUTION","reason":"Diff changes an execution/supply-chain boundary; refuse automatic local project command execution without --allow-risky-exec.","assessment":a,"planned_commands":planned}
    elif not run_commands:
        result={"status":"PASS","local_verification_state":"PLANNED","assessment":a,"planned_commands":planned,"note":"Use --run to execute detected project commands."}
    else:
        runs=[]
        for item in planned:
            cwd=repo/item["workspace"]
            try:
                cp=_run(item["command"],cwd,timeout=300,shell=True)
                runs.append({**item,"returncode":cp.returncode,"stdout":cp.stdout[-4000:],"stderr":cp.stderr[-4000:]})
            except subprocess.TimeoutExpired:
                runs.append({**item,"returncode":124,"stderr":"timeout"})
        failures=[r for r in runs if r["returncode"]!=0]
        if failures: state="FAIL"
        elif not runs: state="INCOMPLETE_NO_PROJECT_COMMANDS"
        elif RISK_ORDER.get(risk,1)>=3 and a.get("specialist_control_count",0)>0: state="LOCAL_PASS_SPECIALIST_EVIDENCE_OUTSTANDING"
        else: state="LOCAL_PASS"
        result={"status":"FAIL" if failures else "PASS","local_verification_state":state,"assessment":a,"runs":runs,"specialist_evidence_outstanding":a.get("specialist_control_count",0) if RISK_ORDER.get(risk,1)>=3 else 0}
    result["actual_execution_contexts"]=actual_execution_contexts
    result["actual_web_detection"]=actual_web_evidence
    result["newly_required_web_procedures"]=newly_required_web_procedures
    if newly_required_web_procedures:
        result["agent_action"]="Load guidance for the actual diff and apply newly routed web/analytics procedures before claiming DONE; then verify again."
        if result.get("local_verification_state") in {"LOCAL_PASS","LOCAL_PASS_SPECIALIST_EVIDENCE_OUTSTANDING"}: result["local_verification_state"]="LOCAL_PASS_NEW_PROCEDURE_REVIEW_REQUIRED"
    sp=_state_path(repo); statefile=_load_json(sp,{}); statefile["last_verification"]={"at":_now(),"revision":_git_head(repo),**{k:v for k,v in result.items() if k not in {"assessment","runs"}},"risk":risk,"triggers":sorted(triggers)}; statefile["updated_at"]=_now(); _write_json(sp,statefile)
    return result

# ---------- release readiness ----------
def release(repo):
    repo=Path(repo).resolve(); blockers=[]; warnings=[]; head=_git_head(repo); dirty=_git_dirty(repo); profile=_load_json(repo/".sef/project-profile.json",{}); baseline=_load_json(repo/".sef/project-baseline.json",{}); state=_load_json(_state_path(repo),{})
    if head is None: blockers.append("No exact Git revision available.")
    if dirty: blockers.append("Working tree is dirty; release identity does not match a committed exact revision.")
    if not baseline.get("project",{}).get("brief"): blockers.append("Project brief/baseline discovery is incomplete.")
    unresolved=sorted(set(
        [c.get("context") for c in profile.get("context_candidates",[]) if c.get("context") in MATERIAL_CONFIRMATIONS]
        + [ctx for ctx in baseline.get("discovery",{}).get("context_confirmations_needed",[]) if ctx in MATERIAL_CONFIRMATIONS]
    ))
    if unresolved: blockers.append("Material project contexts remain unconfirmed: "+", ".join(sorted(set(unresolved))))
    lv=state.get("last_verification") or {}
    if not lv: blockers.append("No recorded verification exists for this project state.")
    elif lv.get("revision")!=head: blockers.append("Last verification is not tied to the current HEAD revision.")
    elif lv.get("local_verification_state") not in {"LOCAL_PASS","LOCAL_PASS_SPECIALIST_EVIDENCE_OUTSTANDING"}: blockers.append("Last local verification is not passing.")
    if lv.get("local_verification_state")=="LOCAL_PASS_SPECIALIST_EVIDENCE_OUTSTANDING": blockers.append("Specialist evidence is still outstanding; local command success is not sufficient for production VERIFIED.")
    readiness="BLOCKED" if blockers else "READY_FOR_RELEASE_REVIEW"
    result={"status":"PASS" if not blockers else "BLOCKED","release_readiness":readiness,"revision":head,"blockers":blockers,"warnings":warnings,"note":"READY_FOR_RELEASE_REVIEW is not an automatic deployment. R3/R4/human gates remain policy-controlled."}
    state["last_release_check"]={"at":_now(),**result}; state["updated_at"]=_now(); _write_json(_state_path(repo),state)
    return result

# ---------- health ----------
def self_test():
    td,root=_runtime_root(); checks=[]
    try:
        for cmd in [[sys.executable,"tools/sef.py","validate"],[sys.executable,"tools/validate_specialist_packs.py"],[sys.executable,"tools/sef.py","regression"]]:
            cp=_run(cmd,root,timeout=120); checks.append({"command":" ".join(cmd),"returncode":cp.returncode,"stdout":cp.stdout.strip()[-1200:]})
        return {"status":"PASS" if all(x["returncode"]==0 for x in checks) else "FAIL","checks":checks}
    finally: td.cleanup()

def doctor(repo):
    repo=Path(repo).resolve(); issues=[]; warnings=[]
    for rel in ["AGENTS.md","CLAUDE.md",".sef/sef.py",".sef/project-profile.json",".sef/project-baseline.json",".sef/installation.json",".agents/skills/senior-engineering-framework/SKILL.md"]:
        if not (repo/rel).exists(): issues.append("missing "+rel)
    if (repo/"AGENTS.md").exists() and MANAGED_BEGIN not in (repo/"AGENTS.md").read_text(encoding="utf-8",errors="ignore"): issues.append("SEF Project OS v1.4 managed block missing from AGENTS.md")
    if (repo/"CLAUDE.md").exists() and "<!-- SEF:BEGIN claude-adapter managed v1.4 -->" not in (repo/"CLAUDE.md").read_text(encoding="utf-8",errors="ignore"): issues.append("SEF Claude Code v1.4 managed block missing from CLAUDE.md")
    st=self_test()
    if st["status"]!="PASS": issues.append("embedded policy self-test failed")
    if repo.exists():
        fresh=scan(repo); current=_load_json(repo/".sef/project-profile.json",{})
        missing=sorted(set(fresh.get("contexts",[]))-set(current.get("contexts",[])))
        if missing: warnings.append("profile context drift: "+str(missing))
    return {"status":"PASS" if not issues else "FAIL","issues":issues,"warnings":warnings,"self_test":st["status"],"managed_sef_files":7}

def export_policy(out):
    out=Path(out).resolve(); out.mkdir(parents=True,exist_ok=True); td,root=_runtime_root()
    try:
        for rel in [".sef/policy",".sef/packs",".sef/packs.json",".sef/bootstrap-detection-rules.json"]:
            src=root/rel; dst=out/rel
            if src.is_dir(): shutil.copytree(src,dst,dirs_exist_ok=True)
            else: dst.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(src,dst)
        return {"status":"PASS","exported_to":str(out)}
    finally: td.cleanup()

def _resolve_cli_text(direct="",file_path=None,label="text"):
    if direct and file_path:
        return None,{"status":"BLOCKED","reason":"AMBIGUOUS_INPUT","message":f"Provide either inline {label} or --{label}-file, not both."}
    if file_path:
        try:
            text=Path(file_path).read_text(encoding="utf-8")
        except Exception as e:
            return None,{"status":"BLOCKED","reason":"INPUT_FILE_READ_FAILED","message":str(e),"file":str(file_path)}
        return text.strip(),None
    return str(direct or "").strip(),None

